import { Treemap, hierarchy, treemapSquarify } from '@visx/hierarchy';
import React, { PropsWithChildren, forwardRef, useMemo } from 'react';

import { TreemapCanvas } from './TreeMapCanvas.js';
import { Canvas } from '../../core/components/canvas/Canvas.js';
import { CanvasContext } from '../../core/components/canvas/CanvasContext.js';
import { CanvasShape } from '../../core/components/canvas/types/canvas-shape.js';
import { useGraphSize } from '../../core/components/chart-layout/hooks/useGraphSize.js';
import { useTreeMapData } from '../context/TreeMapDataContext.js';
import { nodePadding } from '../functions/node-padding.js';
import { useAggregatedData } from '../hooks/useAggregatedData.js';
import { useFilteredData } from '../hooks/useFilteredData.js';
import { useHighlightedState } from '../store/selectors.js';

interface TreeMapInternalProps {
  minNodeSize: number;
}

export const TreeMapInternal = forwardRef<
  HTMLDivElement,
  PropsWithChildren<TreeMapInternalProps>
>((props, forwardedRef): JSX.Element => {
  const { minNodeSize, children } = props;
  const { width, height } = useGraphSize();
  const data = useTreeMapData();

  const treemapArea = width * height;

  const filterdData = useFilteredData(data);
  const filteredAggregatedData = useAggregatedData(
    filterdData,
    treemapArea,
    minNodeSize,
  );

  // build hierarchy with concrete coordinates and width/size of nodes based on tree structure
  const root = useMemo(
    () => hierarchy(filteredAggregatedData),
    [filteredAggregatedData],
  );

  const highlightedItems = useHighlightedState();

  return (
    <div ref={forwardedRef}>
      {children}
      <CanvasContext.Provider
        value={{
          shapeRefs: new Map<string, React.MutableRefObject<CanvasShape>>(),
        }}
      >
        <Canvas width={width} height={height}>
          <Treemap
            root={root}
            size={[width, height]}
            tile={treemapSquarify}
            padding={nodePadding}
            round
          >
            {(node) => (
              <TreemapCanvas
                treemap={node}
                width={width}
                height={height}
                highlightedItems={highlightedItems}
              />
            )}
          </Treemap>
        </Canvas>
      </CanvasContext.Provider>
    </div>
  );
});
